(function () {
    var panel = $.GetContextPanel();
    var debugId = Math.floor(Math.random() * 1000); // 区分不同实例的ID
    function updateStars() {
        var label = panel.FindChildTraverse("StarsLabel");
        if (!label) {
            $.Msg("[WP JS] StarsLabel not found in panel ", debugId);
            return;
        }
        var data = panel.Data || {};
        if (!data) {
            // 如果数据还没准备好，继续轮询
            $.Schedule(0.1, updateStars);
            return;
        }

        if (label.text !== data.stars) {
            $.Msg("[WP JS] Updating stars for ID: ", debugId, " Value: ", data.stars);
            label.text = data.stars || "";
        }

        $.Schedule(0.5, updateStars); // 降低频率以节省性能
    }

    updateStars();
})();
